// One row per write the assistant runs (direct or confirmed), including
// failures. The summary is server-built, never model words.
export const assistantActions = sqliteTable(
  "assistant_actions",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    ownerId: text().references(() => user.id, { onDelete: "set null" }),
    tool: text().notNull(),
    summary: text().notNull(),
    status: text().notNull(),
    ...timestamps(),
  },
  (table) => [index("assistant_actions_business_idx").on(table.businessId)]
)

// One saved owner-assistant chat per row. The id is a UUID made by the
// browser; messages is JSON of AssistantMessage[]. The title is the
// first owner message, set once on create and never changed after.
export const assistantConversations = sqliteTable(
  "assistant_conversations",
  {
    id: text().primaryKey(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    ownerId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text().notNull(),
    messages: text().notNull(),
    ...timestamps(),
  },
  (table) => [
    index("assistant_conversations_owner_idx").on(
      table.businessId,
      table.ownerId,
      table.updatedAt
    ),
  ]
)

// A business's "Connect with Koblip Chat" connection, one per business
// (docs/koblip-chat-integration.md, step 1). Both tokens are encrypted with
// lib/secret-box and never leave the server. When Chat refuses a refresh the
// tokens are dropped and needsReconnect asks the owner to connect again.
export const chatConnections = sqliteTable("chat_connections", {
  businessId: text()
    .primaryKey()
    .references(() => businesses.id, { onDelete: "cascade" }),
  workspaceId: text().notNull(),
  workspaceName: text().notNull(),
  scopes: text().notNull(),
  accessToken: text(),
  refreshToken: text(),
  accessExpiresAt: text(),
  needsReconnect: integer({ mode: "boolean" }).notNull().default(false),
  // The WhatsApp account and number Book's messages use, Chat's own ids
  // (step 2); empty until the workspace has an active number.
  wabaId: text(),
  phoneNumberId: text(),
  ...timestamps(),
})

// Koblip's own Koblip Chat workspace, which sends for every business that has
// not connected its own (K1). One row, connected once by an admin; kept apart
// from chatConnections so no business can reach it. Same token handling.
export const koblipChatConnection = sqliteTable("koblip_chat_connection", {
  id: text({ enum: ["koblip"] }).primaryKey(),
  workspaceId: text().notNull(),
  workspaceName: text().notNull(),
  scopes: text().notNull(),
  accessToken: text(),
  refreshToken: text(),
  accessExpiresAt: text(),
  needsReconnect: integer({ mode: "boolean" }).notNull().default(false),
  wabaId: text(),
  phoneNumberId: text(),
  // The admin who connected it.
  connectedBy: text().references(() => user.id, { onDelete: "set null" }),
  ...timestamps(),
})

// Book's booking templates in the business's Koblip Chat, one per message and
// language (docs/koblip-chat-integration.md, step 2): Chat's template id and
// Meta's review status and reason, as Chat last reported them. A row exists
// once the owner submitted the message to Meta, or Chat already had it.
export const chatTemplates = sqliteTable(
  "chat_templates",
  {
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    message: text({
      enum: ["confirmed", "reminder", "changed", "cancelled", "ownerNewBooking"],
    }).notNull(),
    language: text({ enum: ["en", "es"] }).notNull(),
    chatTemplateId: text().notNull(),
    status: text().notNull(),
    // Meta's words when it refused the template.
    reason: text(),
    // What the owner submitted: the approved template is sent with its own
    // fields, and a newer wording shows as not submitted. None for a
    // template Chat already had.
    submitted: text({ mode: "json" }).$type<{
      header: string
      body: string
      footer: string
      buttons: { action: "confirm" | "cantCome" | "ok"; label: string }[]
    }>(),
    ...timestamps(),
  },
  (table) => [primaryKey({ columns: [table.businessId, table.message, table.language] })]
)

// A business's WhatsApp notification settings, as its owner set them on the
// WhatsApp page; no row means the defaults in lib/notification-rules.ts.
export const notificationSettings = sqliteTable("notification_settings", {
  businessId: text()
    .primaryKey()
    .references(() => businesses.id, { onDelete: "cascade" }),
  // Where the owner's "New booking" alert goes (E.164), or none.
  ownerPhone: text(),
  // The language the owner's alert goes in: the one they use Book in.
  ownerLanguage: text({ enum: ["en", "es"] }).notNull().default("en"),
  // Minutes before the visit, longest first.
  reminders: text({ mode: "json" }).$type<number[]>().notNull(),
  quietStart: text().notNull(),
  quietEnd: text().notNull(),
  // The messages the owner turned off.
  turnedOff: text({ mode: "json" })
    .$type<("confirmed" | "reminder" | "changed" | "cancelled" | "ownerNewBooking")[]>()
    .notNull(),
  // Inside the 24-hour window, a normal message instead of the template.
  freeTextInWindow: integer({ mode: "boolean" }).notNull().default(true),
  // What a customer's "Can't make it" does.
  cantCome: text({ enum: ["cancel", "alertOnly"] }).notNull().default("alertOnly"),
  thankYouReply: integer({ mode: "boolean" }).notNull().default(true),
  ...timestamps(),
})

// The owner's own wording for one message in one language; no row means
// Book's default (features/dashboard/utils/booking-templates.ts). Fields are
// written as {name}, {service}… and become Meta's {{1}}… when sent to Chat.
export const notificationTexts = sqliteTable(
  "notification_texts",
  {
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    message: text({
      enum: ["confirmed", "reminder", "changed", "cancelled", "ownerNewBooking"],
    }).notNull(),
    language: text({ enum: ["en", "es"] }).notNull(),
    header: text().notNull(),
    body: text().notNull(),
    footer: text().notNull(),
    // The owner's buttons; none means Book's default buttons.
    buttons: text({ mode: "json" }).$type<{ action: "confirm" | "cantCome" | "ok"; label: string }[]>(),
    ...timestamps(),
  },
  (table) => [primaryKey({ columns: [table.businessId, table.message, table.language] })]
)

// Every WhatsApp booking message Book plans for a booking, and what became of
// it: one row per booking, message and reminder time, so nothing goes twice.
export const notificationSends = sqliteTable(
  "notification_sends",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    bookingId: text()
      .notNull()
      .references(() => bookings.id, { onDelete: "cascade" }),
    message: text({
      enum: ["confirmed", "reminder", "changed", "cancelled", "ownerNewBooking"],
    }).notNull(),
    // Minutes before the visit for a reminder; 0 for the other messages.
    reminderMinutes: integer().notNull().default(0),
    // The booking's moves when this row was made: a moved booking gets its
    // own "changed" message and reminders (D5).
    moves: integer().notNull().default(0),
    dueAt: text().notNull(),
    // pending → sending → sent | failed; skipped when it must not go.
    state: text({ enum: ["pending", "sending", "sent", "failed", "skipped"] }).notNull(),
    // Why it was skipped or failed (a short code).
    reason: text(),
    // How it went: plain text inside the 24-hour window, else the template.
    via: text({ enum: ["text", "template"] }),
    // Chat's record id, and WhatsApp's delivery status from Chat's events.
    chatRecordId: text(),
    delivery: text(),
    sentAt: text(),
    // Koblip's number (the default) or the business's own.
    sender: text({ enum: ["koblip", "own"] }).notNull().default("own"),
    // The customer's tap on one of the message's buttons.
    replyAction: text({ enum: ["confirm", "cantCome", "ok"] }),
    repliedAt: text(),
    ...timestamps(),
  },
  (table) => [
    uniqueIndex("notification_sends_once").on(
      table.bookingId,
      table.message,
      table.reminderMinutes,
      table.moves
    ),
    index("notification_sends_due").on(table.state, table.dueAt),
    index("notification_sends_business").on(table.businessId, table.createdAt),
    index("notification_sends_record").on(table.chatRecordId),
  ]
)

// When each customer last wrote to a WhatsApp number of a connected Chat
// workspace, from Chat's signed events (docs/koblip-chat-integration.md,
// step 2). Meta's 24-hour window runs from this, per business number and
// customer: inside it Book may send plain text, outside it only a template.
export const chatReplies = sqliteTable(
  "chat_replies",
  {
    workspaceId: text().notNull(),
    // Chat's id for the business's WhatsApp number (the event's senderId).
    phoneNumberId: text().notNull(),
    // The customer's number, digits only, as WhatsApp sends it.
    customerPhone: text().notNull(),
    lastReplyAt: text().notNull(),
    ...timestamps(),
  },
  (table) => [
    primaryKey({ columns: [table.workspaceId, table.phoneNumberId, table.customerPhone] }),
  ]
)

// The admin's values for the app's rules, over the defaults in code
// (lib/notification-rules.ts, A0). A rule with no row uses its default.
// Values are JSON; lib/platform-settings.ts checks each against its rule.
export const platformSettings = sqliteTable("platform_settings", {
  key: text().primaryKey(),
  value: text({ mode: "json" }).$type<unknown>().notNull(),
  updatedBy: text().references(() => user.id, { onDelete: "set null" }),
  ...timestamps(),
})

// One business's own value for a rule the admin may set per business, such
// as its monthly limit on Koblip's number (D3). Over platformSettings.
export const businessSettings = sqliteTable(
  "business_settings",
  {
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    key: text().notNull(),
    value: text({ mode: "json" }).$type<unknown>().notNull(),
    updatedBy: text().references(() => user.id, { onDelete: "set null" }),
    ...timestamps(),
  },
  (table) => [primaryKey({ columns: [table.businessId, table.key] })]
)

// Every change to a rule: who, when, which rule, for everyone or one
// business, and the value before and after (null = the default).
export const platformSettingChanges = sqliteTable(
  "platform_setting_changes",
  {
    id: integer().primaryKey({ autoIncrement: true }),
    key: text().notNull(),
    businessId: text().references(() => businesses.id, { onDelete: "cascade" }),
    before: text({ mode: "json" }).$type<unknown>(),
    after: text({ mode: "json" }).$type<unknown>(),
    changedBy: text().references(() => user.id, { onDelete: "set null" }),
    changedAt: text()
      .notNull()
      .$defaultFn(() => new Date().toISOString()),
  },
  (table) => [index("platform_setting_changes_changed_at_idx").on(table.changedAt)]
)
